/** CTLVERS: catálogo de versiones que traduce un identificador lógico al título del objeto vigente. */
public interface CatalogoVersiones {
    Optional<String> titulo(String idLogico);      // DAME_TIT(ID, TITULO) < 0 -> Optional.empty()
    boolean checaVersion(String id, String version);  // CHECAME: declarado en P046 pero no se usa
}

/** INPUTHEADER / OUTPUTHEADER de COMS: en Java, canales de entrada y salida del adaptador COMS. */
@Configuration
public class RevocacionesConfig {
    @Bean MessageChannel comsEntrada() { return new QueueChannel(); }        // COMSINHDR
    @Bean MessageChannel comsSalida()  { return new DirectChannel(); }       // COMSOUTHDR
}

/**
 * Contrato de la librería TIME_OUT (S500L046REVO). Es la misma firma que exporta L093:
 * encabezados COMS de entrada y salida y dos eventos que despiertan al procedimiento.
 */
public interface CancelacionesPort {
    /** Bloquea hasta que COMS ordena terminar (en L093, RECEIVE con resultado 99). */
    void enviaCancelaciones(MessageChannel comsEntrada, MessageChannel comsSalida);
}

# application.yml
p046:
  libreria-revocaciones:
    id-logico: "S500L046REVO"
    titulo-respaldo: "(S500)S500/OBJECT/L046/REVOCA/25MTP002 ON CAPTACION"

// ---------------------------------------------------------------------------
@Component
@RequiredArgsConstructor
class ResolucionLibreria {

    private final CatalogoVersiones ctlvers;
    private final P046Properties props;

    /** IF DAME_TIT(...) < 0 THEN título fijo ELSE título del catálogo (72 caracteres). */
    String tituloLibreria() {
        var lib = props.libreriaRevocaciones();
        return ctlvers.titulo(lib.idLogico())
                .map(t -> t.length() > 72 ? t.substring(0, 72) : t)
                .orElseGet(() -> {
                    log.warn("CTLVERS sin título para {}; se usa respaldo {}", lib.idLogico(), lib.tituloRespaldo());
                    return lib.tituloRespaldo();
                });
    }
}

@Component
class NombreListado implements ApplicationListener<ApplicationStartingEvent> {

    /** S500/LIST/P046/1000/R000/{TIME(15)}. : un listado por ejecución. */
    @Override
    public void onApplicationEvent(ApplicationStartingEvent e) {
        String sello = DateTimeFormatter.ofPattern("yyyyMMddHHmmssSSS")
                .withZone(ZoneId.of("America/Mexico_City"))
                .format(Instant.now());
        System.setProperty("LOG_FILE", "logs/s500/p046/1000/r000/" + sello + ".log");   // MYSELF.BDNAME
    }
}

@SpringBootApplication
@EnableConfigurationProperties(P046Properties.class)
public class P046Application {
    public static void main(String[] args) { SpringApplication.run(P046Application.class, args); }

    /** ENABLE(COMSINHDR,"ONLINE") y llamada a ENVIA_CANCELACIONES; al regresar, END. */
    @Bean
    ApplicationRunner arranque(CancelacionesPort cancelaciones, ComsAdapter coms,
                               MessageChannel comsEntrada, MessageChannel comsSalida,
                               ConfigurableApplicationContext ctx) {
        return args -> {
            coms.habilita("ONLINE");
            cancelaciones.enviaCancelaciones(comsEntrada, comsSalida);   // bloquea hasta la orden de fin
            ctx.close();
        };
    }
}
